internal static class YazilimBorsasiHtml
{
    public const string Icerik = """
<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Yazılım Borsası V9.2</title><style>
:root{color-scheme:dark;--bg:#030712;--p:#0b1424;--p2:#111f34;--l:#263b58;--t:#eff8ff;--m:#8fa8c8;--g:#45e3a3;--b:#58a6ff;--r:#ff6b7b;--y:#ffd166;--v:#b987ff}*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:radial-gradient(circle at 5% 0,#163966 0,transparent 30%),radial-gradient(circle at 95% 0,#3d195d 0,transparent 28%),var(--bg);color:var(--t);font-family:Segoe UI,Arial,sans-serif}body{padding:10px}.shell{max-width:2200px;margin:auto}.top{position:sticky;top:5px;z-index:30;padding:12px 15px;border:1px solid var(--l);border-radius:16px;background:#06101df2;backdrop-filter:blur(14px);display:flex;justify-content:space-between;gap:12px;align-items:center}.brand{font-weight:1000;font-size:20px}.brand small{display:block;color:var(--m);font-size:9px}.row,.tabs{display:flex;gap:7px;align-items:center;flex-wrap:wrap}.pill,.tag{padding:5px 8px;border:1px solid var(--l);border-radius:999px;background:#091528;color:var(--m);font-size:9px}.tabs{margin:10px 0}.tab{cursor:pointer;border:1px solid var(--l);border-radius:9px;padding:8px 11px;background:#091528;color:var(--t);font-weight:900}.tab.active{background:linear-gradient(135deg,var(--g),var(--b));color:#02151c}.metrics{display:grid;grid-template-columns:repeat(8,minmax(110px,1fr));gap:7px;margin:10px 0}.metric,.card,.company,.news,.item{border:1px solid var(--l);border-radius:13px;background:linear-gradient(180deg,var(--p2),#081321)}.metric{padding:9px}.metric span,.sub{display:block;color:var(--m);font-size:8px}.metric b{display:block;margin-top:5px;font-size:15px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.grid3{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px}.grid4{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px}.card,.company,.news,.item{padding:11px}.company{position:relative;overflow:hidden}.company:before{content:"";position:absolute;inset:0 auto 0 0;width:4px;background:linear-gradient(var(--g),var(--b))}.rank{font-size:28px;font-weight:1000;color:var(--y)}.price{font-size:25px;font-weight:1000}.good{color:var(--g)}.bad{color:var(--r)}.warn{color:var(--y)}.bar{height:9px;background:#15233a;border-radius:99px;overflow:hidden}.bar i{display:block;height:100%;background:linear-gradient(90deg,var(--b),var(--g))}.tablewrap{overflow:auto;max-height:700px;scrollbar-gutter:stable}table{width:100%;border-collapse:collapse;min-width:1000px;font-size:9px}th{position:sticky;top:0;background:#101c30;color:var(--m);padding:8px;text-align:left;z-index:2}td{padding:8px;border-bottom:1px solid #1b2a41;vertical-align:top}.ticker{overflow:hidden;border:1px solid #73572a;border-radius:12px;background:linear-gradient(90deg,#2b1608,#3b2509,#201009);margin:10px 0}.ticker div{white-space:nowrap;display:inline-block;padding:9px 0;font-weight:900;color:#ffe2a3;animation:move 180s linear infinite}.ticker:hover div{animation-play-state:paused}@keyframes move{from{transform:translateX(100vw)}to{transform:translateX(-100%)}}.hero{padding:20px;border:1px solid #7653ac;border-radius:16px;background:linear-gradient(135deg,#241342,#0a2440);box-shadow:0 0 40px #764fbc33}.hero h1{font-size:28px;margin:5px 0}.news{position:relative}.news.critical{border-color:#ff6b7b;box-shadow:0 0 25px #ff405533}.news.headline{border-color:#ffd166;box-shadow:0 0 25px #ffd16622}.badge{display:inline-block;padding:4px 8px;border-radius:999px;background:#283b56;color:#cfe7ff;font-size:8px;font-weight:1000}.flash{background:#8c1f32;color:white}.headlineBadge{background:#765719;color:#fff0b0}.title{display:flex;justify-content:space-between;align-items:center;gap:8px}.title h2,.item h3{margin:0}.spark{display:flex;gap:2px;align-items:flex-end;height:50px}.spark i{flex:1;min-width:3px;background:linear-gradient(var(--g),var(--b));border-radius:2px}.empty{color:var(--m);padding:30px;text-align:center}@media(max-width:1500px){.metrics{grid-template-columns:repeat(4,1fr)}.grid4{grid-template-columns:repeat(2,1fr)}}@media(max-width:900px){.top{position:static;flex-direction:column;align-items:flex-start}.metrics,.grid,.grid3,.grid4{grid-template-columns:1fr}}
</style></head><body><div class="shell"><header class="top"><div class="brand">YAZILIM BORSASI V9.2<small>Şirket değerleri · piyasa payları · arz-talep · canlı haber merkezi</small></div><div class="row"><span class="pill">Tick <b id="tick">0</b></span><span class="pill">Şirket <b id="companies">0</b></span><span class="pill">Müşteri <b id="customers">0</b></span><span class="pill">Durum <b id="status">Bağlanıyor</b></span></div></header><div id="ticker" class="ticker"><div>Yazılım piyasası açılıyor…</div></div><section id="metrics" class="metrics"></section><nav id="tabs" class="tabs"></nav><main id="root"></main></div><script>
'use strict';const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=v=>new Intl.NumberFormat('tr-TR',{style:'currency',currency:'TRY',maximumFractionDigits:2}).format(Number(v||0)),num=v=>new Intl.NumberFormat('tr-TR',{maximumFractionDigits:2}).format(Number(v||0)),int=v=>new Intl.NumberFormat('tr-TR',{maximumFractionDigits:0}).format(Number(v||0));
const T=[['home','Genel'],['exchange','Borsa'],['market','Arz & Talep'],['products','Uygulama & OS'],['news','Haber Bülteni'],['customers','Müşteri CV'],['services','Hizmet Pazarı']];const S={d:null,a:T.some(x=>x[0]===location.hash.slice(1))?location.hash.slice(1):'home',last:-1,loading:false,hold:0,pending:false};
function tabs(){$('#tabs').innerHTML=T.map(x=>`<button class="tab ${S.a===x[0]?'active':''}" data-tab="${x[0]}">${x[1]}</button>`).join('')}function tab(id){S.a=T.some(x=>x[0]===id)?id:'home';history.replaceState(null,'',`#${S.a}`);tabs();render(true)}function editing(){return Date.now()<S.hold}function positions(){const m={w:scrollY};document.querySelectorAll('[data-scroll]').forEach(x=>m[x.dataset.scroll]=x.scrollTop);return m}function restore(m){requestAnimationFrame(()=>{scrollTo(0,m.w||0);document.querySelectorAll('[data-scroll]').forEach(x=>{if(m[x.dataset.scroll]!=null)x.scrollTop=m[x.dataset.scroll]})})}
async function refresh(){if(S.loading)return;S.loading=true;try{const r=await fetch('/api/durum',{cache:'no-store'});if(!r.ok)throw Error(r.status);const d=await r.json(),t=Number(d.motor?.tickNumarasi||0);S.d=d;$('#tick').textContent=t;$('#companies').textContent=d.genel?.bagliSirket+'/'+d.genel?.toplamSirket;$('#customers').textContent=int(d.genel?.aktifMusteri);$('#status').textContent='Canlı';if(t!==S.last){S.last=t;render()}}catch{$('#status').textContent='Bağlantı yok'}finally{S.loading=false}}
function metrics(d){const g=d.genel||{},ss=d.sirketler||[];return [['Toplam şirket değeri',money(ss.reduce((a,x)=>a+Number(x.sirketDegeri||0),0))],['Toplam kasa',money(g.toplamKasa)],['Tick gelir',money(Number(g.toplamUygulamaGeliri||0)+Number(g.toplamHizmetGeliri||0))],['Tick gider',money(g.toplamGider)],['Tick net',money(g.toplamNet)],['Hizmet talebi',int(g.hizmetTalebi)],['OS karşılanan',`${int(g.osKarsilanan)}/${int(g.osTalebi)}`],['Uygulama',int(d.uygulamalar?.length)]].map(x=>`<div class="metric"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}
function render(force=false){if(!S.d)return;const p=positions();$('#metrics').innerHTML=metrics(S.d);ticker(S.d);const f={home,exchange,market,products,news,customers,services}[S.a]||home;$('#root').innerHTML=f(S.d);restore(p)}
function ticker(d){const h=(d.haberler||[]).slice(0,18);$('#ticker').innerHTML=`<div>${h.map(x=>`${esc(x.ikon||'📰')} ${esc(x.baslik||x.aciklama)}`).join('　✦　')||'Piyasa sakin; yeni gelişmeler bekleniyor.'}</div>`}
function home(d){return `${exchange(d)}<div style="height:10px"></div>${news(d,true)}`}
function exchange(d){const ss=[...(d.sirketler||[])].sort((a,b)=>Number(b.sirketDegeri||0)-Number(a.sirketDegeri||0)),total=Math.max(1,ss.reduce((a,x)=>a+Number(x.sirketDegeri||0),0));return `<div class="hero"><span class="badge headlineBadge">CANLI DEĞERLEME</span><h1>Şirketler Borsası</h1><p>Şirket değeri; kasa, düzenli ürün geliri, aboneler, kapasite, kalite, yatırımlar ve borç etkileriyle oluşur.</p></div><div class="grid" style="margin-top:10px">${ss.map((s,i)=>{const value=Number(s.sirketDegeri||0),share=value/10000,marketShare=value*100/total,used=Number(s.kullanilanKapasite||0),cap=Math.max(1,Number(s.toplamKapasite||0)),score=(Number(s.itibarPuani||0)+Number(s.guvenilirlikPuani||0)+Number(s.kodKalitesiPuani||0)+Number(s.performansPuani||0)+Number(s.guvenlikPuani||0)+Number(s.ortalamaMusteriMemnuniyeti||0))/6,rev=Number(s.hizmetGeliri||0)+Number(s.uygulamaGeliri||0)+Number(s.abonelikGeliri||0)+Number(s.protokolGeliri||0);return `<article class="company"><div class="title"><div><span class="rank">#${i+1}</span><h2>${esc(s.sirketAdi)}</h2><span class="tag">${s.bagli?'İŞLEMDE':'KAPALI'}</span></div><div style="text-align:right"><span class="sub">Tahmini hisse</span><div class="price">${money(share)}</div><span class="${Number(s.netKazanc)>=0?'good':'bad'}">${Number(s.netKazanc)>=0?'▲':'▼'} ${money(Math.abs(Number(s.netKazanc||0)))}</span></div></div><div class="grid4"><div class="item"><span class="sub">Şirket değeri</span><b>${money(value)}</b></div><div class="item"><span class="sub">Piyasa payı</span><b>%${num(marketShare)}</b></div><div class="item"><span class="sub">Kasa / borç</span><b>${money(s.kasa)} / ${money(s.borc)}</b></div><div class="item"><span class="sub">Tick ciro</span><b>${money(rev)}</b></div></div><p>Kapasite ${int(used)} / ${int(cap)} · %${num(used*100/cap)}</p><div class="bar"><i style="width:${Math.min(100,used*100/cap)}%"></i></div><p>Ortalama kurumsal skor <b>${num(score)}</b> · Net <b class="${Number(s.netKazanc)>=0?'good':'bad'}">${money(s.netKazanc)}</b></p><div class="spark">${[s.itibarPuani,s.guvenilirlikPuani,s.kodKalitesiPuani,s.performansPuani,s.guvenlikPuani,s.ortalamaMusteriMemnuniyeti].map(x=>`<i style="height:${Math.max(3,Number(x||0))}%"></i>`).join('')}</div><p class="sub">İtibar · güvenilirlik · kalite · performans · güvenlik · memnuniyet</p></article>`}).join('')}</div><div class="card" style="margin-top:10px"><div class="tablewrap" data-scroll="exchange-table"><table><tr><th>Sıra</th><th>Şirket</th><th>Değer</th><th>Hisse</th><th>Kasa</th><th>Borç</th><th>Hizmet geliri</th><th>Uygulama geliri</th><th>Gider</th><th>Net</th><th>Kapasite</th></tr>${ss.map((s,i)=>`<tr><td>#${i+1}</td><td><b>${esc(s.sirketAdi)}</b></td><td>${money(s.sirketDegeri)}</td><td>${money(Number(s.sirketDegeri||0)/10000)}</td><td>${money(s.kasa)}</td><td>${money(s.borc)}</td><td>${money(s.hizmetGeliri)}</td><td>${money(Number(s.uygulamaGeliri||0)+Number(s.abonelikGeliri||0))}</td><td>${money(Number(s.isletmeGideri||0)+Number(s.finansmanGideri||0))}</td><td class="${Number(s.netKazanc)>=0?'good':'bad'}">${money(s.netKazanc)}</td><td>${int(s.kullanilanKapasite)}/${int(s.toplamKapasite)}</td></tr>`).join('')}</table></div></div>`}
function market(d){const apps=d.uygulamaPazari||[],hs=d.hizmetPazari||[],os=d.isletimSistemiPazari||{};return `<div class="grid"><div class="card"><h2>Uygulama kategorileri</h2><div class="tablewrap" data-scroll="app-market"><table><tr><th>Kategori</th><th>Talep</th><th>Karşılanan</th><th>Açık</th><th>Trend</th></tr>${apps.map(x=>`<tr><td>${esc(x.ad)}</td><td>${int(x.buTickTalep)}</td><td>${int(x.karsilananTalep)}</td><td>${int(x.karsilanamayanTalep)}</td><td class="${Number(x.degisimYuzdesi)>=0?'good':'bad'}">${Number(x.degisimYuzdesi)>=0?'▲':'▼'} %${num(Math.abs(x.degisimYuzdesi))}</td></tr>`).join('')}</table></div></div><div class="card"><h2>İşletim sistemi pazarı</h2><p>Talep ${int(os.buTickTalep)} · karşılanan ${int(os.karsilananTalep)} · açık ${int(os.karsilanamayanTalep)}</p>${(os.arzDagilimi||[]).map(x=>`<div class="item"><div class="title"><b>${esc(x.ad)}</b><span class="tag">%${num(x.pazarPayi)}</span></div><p>${esc(x.sirketAdi)} · ${int(x.karsilanan)} kullanıcı · ${money(x.fiyat)}</p></div>`).join('')||'<div class="empty">Aktif işletim sistemi yok.</div>'}<h2>En büyük hizmet açıkları</h2><div class="tablewrap" data-scroll="service-gap"><table><tr><th>Hizmet</th><th>Talep</th><th>Karşılanan</th><th>Açık</th></tr>${hs.slice(0,100).map(x=>`<tr><td>${esc(x.ad)}</td><td>${int(x.buTickTalep)}</td><td>${int(x.karsilananTalep)}</td><td>${int(x.karsilanamayanTalep)}</td></tr>`).join('')}</table></div></div></div>`}
function products(d){const a=d.uygulamalar||[];return `<div class="grid3">${a.map(x=>{const m=x.manifest||{},u=x.urun||{};return `<div class="card"><div class="title"><h2>${esc(m.uygulamaAdi||u.urunAdi)}</h2><span class="tag">${u.aktif?'AKTİF':'PASİF'}</span></div><p>${esc(m.urunTuru||u.urunTuru)} / ${esc(m.kategori||u.kategori)}</p><p>Kullanıcı <b>${int(u.aktifKullaniciSayisi)}</b> / ${int(u.kullaniciKapasitesi)}</p><p>Fiyat ${money(u.fiyatlandirmaModeli==='kullanim'?u.kullanimBasinaUcret:u.abonelikUcreti)}</p><p>Gelir ${money(x.gelir)} · gider ${money(x.gider)}</p><p>${esc(x.dogrulama?.durum||'')}</p></div>`}).join('')||'<div class="empty">Piyasada uygulama yok.</div>'}</div>`}
function news(d,compact=false){const h=(d.haberler||[]).slice(0,compact?8:150),hero=h[0];return `${hero?`<section class="hero"><span class="badge ${hero.onem==='kritik'?'flash':'headlineBadge'}">${esc(hero.rozet||'SON DAKİKA')}</span><h1>${esc(hero.ikon||'📰')} ${esc(hero.baslik)}</h1><p>${esc(hero.aciklama)}</p><b class="${Number(hero.finansalEtki)>=0?'good':'bad'}">${money(hero.finansalEtki)}</b></section>`:''}<div class="grid3" style="margin-top:10px">${h.slice(hero?1:0).map(x=>`<article class="news ${x.onem==='kritik'?'critical':x.onem==='manset'?'headline':''}"><span class="badge ${x.onem==='kritik'?'flash':x.onem==='manset'?'headlineBadge':''}">${esc(x.rozet||x.tur||'HABER')}</span><h2>${esc(x.ikon||'📰')} ${esc(x.baslik)}</h2><p>${esc(x.aciklama)}</p><div class="title"><span class="sub">Tick ${int(x.tickNumarasi)} · ${esc(x.sirketAdi||'Piyasa')}</span><b class="${Number(x.finansalEtki)>=0?'good':'bad'}">${Number(x.finansalEtki)?money(x.finansalEtki):''}</b></div></article>`).join('')||'<div class="empty">Henüz haber yok.</div>'}</div>`}
function customers(d){const c=d.musteriCvleri||[];return `<div class="card"><h2>Müşteri CV kayıtları</h2><div class="tablewrap" data-scroll="cv"><table><tr><th>Müşteri</th><th>Tür</th><th>Gelir</th><th>Bakiye</th><th>İşletim sistemi</th><th>Uygulamalar</th><th>Harcama</th><th>Başarı</th></tr>${c.map(x=>`<tr><td><b>${esc(x.musteriAdi)}</b><br>${esc(x.musteriKimligi)}</td><td>${esc(x.musteriTuru)}<br>${esc(x.meslekProfili)}</td><td>${esc(x.gelirSegmenti)}</td><td>${money(x.bakiye)}</td><td>${esc(x.isletimSistemiKimligi||'Yok')}</td><td>${(x.uygulamalar||[]).map(esc).join('<br>')||'Yok'}</td><td>${money(x.toplamHarcama)}</td><td>${int(x.basariliIsSayisi)} / ${int(x.basarisizIsSayisi)}</td></tr>`).join('')}</table></div></div>`}
function services(d){const hs=d.hizmetPazari||[];return `<div class="card"><h2>500 hizmet piyasası</h2><div class="tablewrap" data-scroll="services"><table><tr><th>Hizmet</th><th>Sabit fiyat</th><th>Talep</th><th>Arz</th><th>Karşılanan</th><th>Açık</th><th>Trend</th></tr>${hs.map(x=>`<tr><td>${esc(x.anahtar)}</td><td>${money(x.sabitFiyat)}</td><td>${int(x.buTickTalep)}</td><td>${int(x.arzKapasitesi)}</td><td>${int(x.karsilananTalep)}</td><td>${int(x.karsilanamayanTalep)}</td><td>${esc(x.aktifTrend)} · %${num(x.degisimYuzdesi)}</td></tr>`).join('')}</table></div></div>`}
document.addEventListener('click',e=>{const b=e.target.closest('[data-tab]');if(b)tab(b.dataset.tab)});addEventListener('scroll',()=>S.hold=Date.now()+600,{passive:true});tabs();refresh();setInterval(refresh,1000);
</script></body></html>
""";
}
